-- Riversmag : corrections validées par le propriétaire (9 nov. 2026). Sauvegarde : branche backup-before-fixes-2026-11-09.
begin;
-- 1) "Maya Chen" est un nom fictif : crédit à l'équipe éditoriale
update "Author" set name='Riversmag Editorial Team', slug='editorial-team', role='Editorial team', location=null, avatar=null, "socialLinks"=null,
  bio='The Riversmag editorial team researches and writes our destination guides, itineraries and travel resources from official tourism and transport sources, partner data and traveller reviews. We correct errors promptly and update guides when prices, rules or practical details change.',
  "updatedAt"=now() where slug='maya-chen';
update "Article" set "authorName"='Riversmag Editorial Team' where "authorName"='Maya Chen';
-- 2) Photos vérifiées pour les destinations sans image (Unsplash, licence gratuite)
update "Destination" d set "coverImage"='https://images.unsplash.com/'||v.photo||'?auto=format&fit=crop&w=1920&q=90', "updatedAt"=now()
  from (values ('athens','photo-1603565816030-6b389eeb23cb'),('bilbao','photo-1636556602097-2435ad5198ef'),('bordeaux','photo-1698608216843-67ae1151b2b8'),('cannes','photo-1659642081573-ac1a040d2e50'),('chefchaouen','photo-1569383746724-6f1b882b8f46'),('chiang-mai','photo-1682826556362-2c06b7ac75c5'),('cordoba','photo-1632904080322-e71e16a5987f'),('essaouira','photo-1624802746702-60ca95bdb605'),('fes','photo-1675782357250-8329a7677819'),('florence','photo-1776377231754-d36928e6ee4d'),('granada','photo-1620677368158-32b1293fac36'),('kamakura','photo-1662554471428-d036dfbc6c45'),('lisbon','photo-1776187007773-aa0f3e56ef4a'),('malaga','photo-1553775556-80669b94bfa5'),('marseille','photo-1566838217578-1903568a76d9'),('milan','photo-1610016302534-6f67f1c968d8'),('montpellier','photo-1690132007585-1ef4b16f49d3'),('nantes','photo-1676283898167-addc4238bee8'),('naples','photo-1593488524895-8f05d3e09181'),('nara','photo-1550303435-1703d8811aaa'),('nice','photo-1643914729809-4aa59fdc4c17'),('porto','photo-1591040973846-61888c2de010'),('san-sebastian','photo-1553455010-bdb488ac12e5'),('santorini','photo-1570077188670-e3a8d69ac5ff'),('sapporo','photo-1572420780547-8fbb45c82f0a'),('seville','photo-1688404808661-92f72f2ea258'),('strasbourg','photo-1596036986070-e84592a19917'),('toulouse','photo-1650707199496-b02442055332'),('valencia','photo-1751834740962-9c41fe457858'),('venice','photo-1514890547357-a9ee288728e0'),('tangier','photo-1633264542743-c1acdb5eff0e'),('oceania','photo-1624138784614-87fd1b6528f8'),('united-states','photo-1527333656061-ca7adf608ae1'),('canada','photo-1561134643-668f9057cce4'),('mexico','photo-1561577101-aa749bffbb70'),('thailand','photo-1613672803979-a6edfc5a179b'),('greece','photo-1509321528270-797a4f7c1485'),('portugal','photo-1616862890964-fd20e9dd106d'),('egypt','photo-1600520611035-84157ad4084d'),('south-africa','photo-1626894169601-482d26b23f35'),('brazil','photo-1483729558449-99ef09a8c325'),('kenya','photo-1619685127973-1d0f61bf25ed'),('tanzania','photo-1564101160531-4838e8a5f4e7')) as v(slug, photo) where d.slug=v.slug and d."coverImage" is null;
update "Article" a set "coverImage"=d."coverImage", "ogImage"=coalesce(a."ogImage", d."coverImage")
  from "Destination" d where d.id=a."destinationId" and a."coverImage" is null and d."coverImage" is not null;
-- 3) Contenus manquants : Paris, Bali, 17 pays, 6 régions
update "Destination" set "overview"=case when length(coalesce("overview",''))<120 then $c$Paris packs world-class museums, café culture and grand boulevards into a compact, walkable city. The Louvre, Musée d'Orsay and Centre Pompidou anchor the art, the Eiffel Tower and Notre-Dame the skyline, while the Marais, Saint-Germain and Montmartre each feel like their own village. Day trips to Versailles and Giverny are easy by train.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$April to June and September to October for mild weather and lighter crowds. July and August are busy and can be hot; many locals leave in August.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Paris Charles de Gaulle (CDG) and Orly (ORY) airports connect to the centre by RER train, bus and taxi. Eurostar links London to Gare du Nord in about 2h20; high-speed TGV trains reach Lyon, Bordeaux, Marseille and Brussels.$c$), "transportation"=coalesce(nullif("transportation",''),$c$The Métro and RER cover the whole city; buy a contactless Navigo Easy card or use a phone wallet. Walking and Vélib' shared bikes work well within the centre.$c$), "budget"=coalesce(nullif("budget",''),$c$Paris is expensive by European standards: central hotels cost more than in most French cities, while bakeries, bistro set lunches and free museum days help keep costs down.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe; pickpocketing is common on the Métro, at major sights and around busy stations.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Schengen area: EU/EEA citizens enter freely; many other nationalities can visit visa-free for short stays. Check the official French government visa site before travel.$c$), "esimInfo"=coalesce(nullif("esimInfo",''),$c$Strong 4G/5G across the city, though signal drops in parts of the Métro. EU eSIMs work throughout France.$c$), "currency"=coalesce(nullif("currency",''),$c$Euro (EUR)$c$), "language"=coalesce(nullif("language",''),$c$French$c$), "timezone"=coalesce(nullif("timezone",''),$c$CET (UTC+1), CEST (UTC+2) in summer$c$), "updatedAt"=now() where slug='paris';
update "Destination" set "overview"=case when length(coalesce("overview",''))<120 then $c$Bali is an Indonesian island known for Hindu temples, terraced rice fields, surf beaches and volcanic highlands. Ubud is the cultural centre, Seminyak and Canggu draw beach and café crowds, and Uluwatu sits on dramatic sea cliffs. Temples such as Tanah Lot, Uluwatu and Besakih are central to island life and best visited respectfully dressed.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$April to October is the dry season with the most reliable weather. November to March brings tropical rain, usually in short heavy bursts, and fewer visitors.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Ngurah Rai International Airport (DPS) near Denpasar has direct flights from across Asia, Australia and the Middle East. Ferries connect to Lombok, the Gili Islands and Java.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Private drivers and ride-hailing apps are the easiest way around; traffic in the south can be slow. Scooters are widely rented but need a valid licence and experience.$c$), "budget"=coalesce(nullif("budget",''),$c$Good value overall: guesthouses and local warungs are inexpensive, while villas, beach clubs and resort areas cost considerably more.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe. Take care with traffic and scooters, strong ocean currents, and drinks served in unlicensed bars.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities need a Visa on Arrival or e-VOA, and a tourist levy applies to foreign visitors. Rules change, so check Indonesia's official immigration site before travel.$c$), "esimInfo"=coalesce(nullif("esimInfo",''),$c$Good 4G in the south and Ubud; coverage thins in the mountains and some rural areas.$c$), "currency"=coalesce(nullif("currency",''),$c$Indonesian Rupiah (IDR)$c$), "language"=coalesce(nullif("language",''),$c$Indonesian, Balinese$c$), "timezone"=coalesce(nullif("timezone",''),$c$WITA (UTC+8)$c$), "updatedAt"=now() where slug='bali';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Beaches, rainforest and carnival energy on a continental scale.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Brazil is South America's largest country, stretching from the Amazon rainforest to the beaches of Rio de Janeiro and the waterfalls of Iguaçu. Salvador carries strong Afro-Brazilian heritage, the Pantanal is one of the best places in the world to see wildlife, and food and music are part of everyday life.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$Varies by region. December to March is summer and carnival season on the coast; the Pantanal is best in the dry season from roughly July to October.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$São Paulo (GRU) and Rio de Janeiro (GIG) are the main international gateways, with flights from Europe, North America and the rest of South America.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Distances are huge, so domestic flights are the practical way between regions. Long-distance buses are comfortable on shorter routes; use ride-hailing apps in cities.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid-range overall; prices are highest in Rio, São Paulo and resort areas.$c$), "safety"=coalesce(nullif("safety",''),$c$Use normal big-city caution: avoid displaying valuables, use registered taxis or apps at night, and follow local advice about specific neighbourhoods.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities visit visa-free; some, including US, Canadian and Australian citizens, need an e-visa. Check Brazil's official consular site before travel.$c$), "currency"=coalesce(nullif("currency",''),$c$Brazilian Real (BRL)$c$), "language"=coalesce(nullif("language",''),$c$Portuguese$c$), "timezone"=coalesce(nullif("timezone",''),$c$Several zones; Brasília time UTC−3$c$), "updatedAt"=now() where slug='brazil';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Mountains, lakes and cosmopolitan cities across a vast landscape.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Canada combines big outdoor landscapes with lively, multicultural cities. The Rockies around Banff and Jasper offer turquoise lakes and mountain hiking, Vancouver sits between ocean and peaks, Montréal and Québec City bring French-speaking culture, and Toronto is the country's largest city.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$June to September for hiking and road trips; December to March for skiing and winter activities. Autumn colours peak in late September and October in the east.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Toronto (YYZ), Vancouver (YVR) and Montréal (YUL) are the main international hubs. Land crossings from the United States are common.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Domestic flights cover long distances; VIA Rail runs scenic routes. A car is the easiest way to explore national parks.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid to high; accommodation near national parks fills up and gets expensive in summer.$c$), "safety"=coalesce(nullif("safety",''),$c$Very safe. In the backcountry, follow park rules on wildlife, especially bears, and prepare for fast weather changes.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Visa-exempt travellers arriving by air usually need an eTA; others need a visitor visa. Check the official Government of Canada site.$c$), "currency"=coalesce(nullif("currency",''),$c$Canadian Dollar (CAD)$c$), "language"=coalesce(nullif("language",''),$c$English, French$c$), "timezone"=coalesce(nullif("timezone",''),$c$Six zones, UTC−3:30 to UTC−8$c$), "updatedAt"=now() where slug='canada';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Pharaonic wonders, the Nile and Red Sea reefs.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Egypt is home to some of the world's most famous ancient sites: the Pyramids of Giza, the temples of Luxor and Karnak, the Valley of the Kings and Abu Simbel. A Nile cruise links many of them, Cairo offers museums and Islamic architecture, and the Red Sea coast is known for diving and snorkelling.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$October to April, when temperatures are comfortable for sightseeing. Summer is very hot in Upper Egypt.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Cairo International (CAI) is the main gateway; Luxor, Aswan, Hurghada and Sharm el-Sheikh also have international flights.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Domestic flights and overnight sleeper trains link Cairo with Luxor and Aswan; Nile cruises cover the stretch between them. Use ride-hailing apps in Cairo.$c$), "budget"=coalesce(nullif("budget",''),$c$Good value for travellers paying in foreign currency, though entry fees at major sites add up.$c$), "safety"=coalesce(nullif("safety",''),$c$Main tourist areas are well policed. Expect persistent touts at major sites, and check your government's travel advice for specific regions.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities can get an e-visa online or a visa on arrival. Check Egypt's official e-visa portal before travel.$c$), "currency"=coalesce(nullif("currency",''),$c$Egyptian Pound (EGP)$c$), "language"=coalesce(nullif("language",''),$c$Arabic$c$), "timezone"=coalesce(nullif("timezone",''),$c$EET (UTC+2), summer time UTC+3$c$), "updatedAt"=now() where slug='egypt';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Art, food, wine and varied landscapes from the Alps to the Riviera.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$France is one of the world's most visited countries, with Paris at its heart and very different regions beyond: the Riviera and Provence in the south, the vineyards of Bordeaux and Burgundy, the châteaux of the Loire, the Alps and the Atlantic coast. High-speed trains make it easy to combine several regions in one trip.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$May, June and September for pleasant weather and fewer crowds. July and August are peak season on the coasts; winter is for skiing in the Alps.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Paris CDG and Orly are the main gateways, with international airports also in Nice, Lyon, Marseille and Bordeaux. Eurostar and high-speed trains connect to London, Brussels, Germany, Switzerland, Italy and Spain.$c$), "transportation"=coalesce(nullif("transportation",''),$c$TGV high-speed trains link the major cities; regional TER trains and buses fill the gaps. A car helps in rural areas such as Provence and the Dordogne.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid to high; Paris and the Riviera are the most expensive, while smaller towns are noticeably cheaper.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe; watch for pickpocketing in large cities and on public transport.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Schengen area: EU/EEA citizens enter freely; many other nationalities can visit visa-free for short stays. Check the official French visa site.$c$), "currency"=coalesce(nullif("currency",''),$c$Euro (EUR)$c$), "language"=coalesce(nullif("language",''),$c$French$c$), "timezone"=coalesce(nullif("timezone",''),$c$CET (UTC+1), CEST (UTC+2) in summer$c$), "updatedAt"=now() where slug='france';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Ancient history, island-hopping and long Aegean summers.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Greece combines ancient sites such as the Acropolis, Delphi and Olympia with thousands of islands. Santorini and Mykonos are the best known, while Crete, Naxos, Rhodes and the Ionian islands offer beaches, villages and hiking. Athens is the usual starting point.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$May, June, September and early October for warm sea and fewer crowds. July and August are hot and very busy on the islands.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Athens International (ATH) is the main hub; many islands, including Crete, Rhodes, Santorini and Corfu, have seasonal international flights.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Ferries connect the islands from Piraeus and Rafina; book ahead in summer. Domestic flights save time on longer routes.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid-range; prices rise sharply on popular islands in peak season.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe; watch for pickpocketing in central Athens and on the metro.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Schengen area: EU/EEA citizens enter freely; many other nationalities can visit visa-free for short stays. Check the official Greek visa site.$c$), "currency"=coalesce(nullif("currency",''),$c$Euro (EUR)$c$), "language"=coalesce(nullif("language",''),$c$Greek$c$), "timezone"=coalesce(nullif("timezone",''),$c$EET (UTC+2), EEST (UTC+3) in summer$c$), "updatedAt"=now() where slug='greece';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Thousands of islands, from Bali's temples to Komodo's dragons.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Indonesia spans more than 17,000 islands. Bali is the most visited, but Java has Borobudur and Prambanan, Lombok and the Gili Islands offer quieter beaches, Komodo National Park is known for its dragons and diving, and Sumatra and Borneo have rainforest and orangutans.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$April to October is generally the dry season across much of the country; November to March is wetter.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Jakarta (CGK) and Bali (DPS) are the main international gateways, with good connections across Asia, Australia and the Middle East.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Domestic flights link the main islands; ferries and fast boats serve shorter hops. Hire drivers or use ride-hailing apps on land.$c$), "budget"=coalesce(nullif("budget",''),$c$Good value overall, with higher prices in resort areas of Bali.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe. Take care with traffic, sea conditions and volcanic activity warnings.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities need a Visa on Arrival or e-VOA. Check Indonesia's official immigration site before travel.$c$), "currency"=coalesce(nullif("currency",''),$c$Indonesian Rupiah (IDR)$c$), "language"=coalesce(nullif("language",''),$c$Indonesian$c$), "timezone"=coalesce(nullif("timezone",''),$c$Three zones, UTC+7 to UTC+9$c$), "updatedAt"=now() where slug='indonesia';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Art cities, coastlines and regional food in every town.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Italy offers a remarkable concentration of art and history in Rome, Florence and Venice, alongside the lakes and Alps of the north, the hill towns of Tuscany and Umbria, the Amalfi Coast and the islands of Sicily and Sardinia. Every region has its own cooking.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$April to June and September to October for comfortable sightseeing. August is hot and many locals are on holiday.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Rome Fiumicino (FCO) and Milan Malpensa (MXP) are the main hubs, with international airports also in Venice, Naples, Florence and Catania.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Fast Frecciarossa and Italo trains link the major cities; regional trains and buses cover smaller towns. A car is useful in Tuscany and the south.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid-range; Venice, Rome, Florence and the Amalfi Coast are the most expensive.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe; watch for pickpockets in crowded tourist areas and on public transport.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Schengen area: EU/EEA citizens enter freely; many other nationalities can visit visa-free for short stays. Check the official Italian visa site.$c$), "currency"=coalesce(nullif("currency",''),$c$Euro (EUR)$c$), "language"=coalesce(nullif("language",''),$c$Italian$c$), "timezone"=coalesce(nullif("timezone",''),$c$CET (UTC+1), CEST (UTC+2) in summer$c$), "updatedAt"=now() where slug='italy';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Neon cities, ancient temples and precise, welcoming culture.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Japan pairs ultra-modern cities with deep tradition. Tokyo and Osaka are fast-paced and full of food, Kyoto and Nara preserve temples and gardens, Hiroshima and Miyajima are moving and scenic, and Hokkaido offers snow and wide landscapes. Public transport is excellent everywhere.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$Late March to May for cherry blossoms and mild weather; October and November for autumn colours. Summer is hot and humid; winter is good for skiing in the north.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Tokyo Narita (NRT) and Haneda (HND) and Osaka Kansai (KIX) are the main international airports.$c$), "transportation"=coalesce(nullif("transportation",''),$c$The Shinkansen bullet train links the major cities; local trains and subways are reliable and punctual. IC cards such as Suica and ICOCA make fares easy.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid-range; hotels in Tokyo and Kyoto cost more at peak seasons, while convenience-store and casual meals are good value.$c$), "safety"=coalesce(nullif("safety",''),$c$Very safe, with low crime. Be prepared for earthquakes and follow local alerts.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities can enter visa-free for short stays. Check the official Ministry of Foreign Affairs of Japan site.$c$), "currency"=coalesce(nullif("currency",''),$c$Japanese Yen (JPY)$c$), "language"=coalesce(nullif("language",''),$c$Japanese$c$), "timezone"=coalesce(nullif("timezone",''),$c$JST (UTC+9)$c$), "updatedAt"=now() where slug='japan';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Classic safari country, from the Maasai Mara to the Indian Ocean.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Kenya is one of Africa's best-known safari destinations. The Maasai Mara hosts the Great Migration, Amboseli has elephant herds below Kilimanjaro, and Samburu and Tsavo offer quieter game drives. The coast around Diani and Lamu adds beaches and Swahili culture.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$July to October for the Great Migration in the Maasai Mara; January and February are also dry and good for wildlife.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Nairobi Jomo Kenyatta International (NBO) is the main gateway; Mombasa (MBA) serves the coast.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Safari circuits are usually done with a guided operator by road or by light aircraft to park airstrips. Use registered taxis or ride-hailing apps in Nairobi.$c$), "budget"=coalesce(nullif("budget",''),$c$Safaris are the main cost and range from budget camping to high-end lodges; park fees are significant.$c$), "safety"=coalesce(nullif("safety",''),$c$Use city caution in Nairobi and Mombasa and check your government's travel advice for border regions. Follow guides' instructions on safari.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Most visitors need an Electronic Travel Authorisation (eTA) applied for online before travel. Check Kenya's official eTA portal.$c$), "currency"=coalesce(nullif("currency",''),$c$Kenyan Shilling (KES)$c$), "language"=coalesce(nullif("language",''),$c$English, Swahili$c$), "timezone"=coalesce(nullif("timezone",''),$c$EAT (UTC+3)$c$), "updatedAt"=now() where slug='kenya';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Ancient ruins, Caribbean beaches and one of the world's great cuisines.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Mexico ranges from the Maya ruins and cenotes of the Yucatán to colonial cities such as Oaxaca, San Miguel de Allende and Guanajuato, and the huge, creative capital, Mexico City. The Caribbean and Pacific coasts offer beaches, and Mexican food is a highlight everywhere.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$November to April is the dry season in most regions. Hurricane season on the coasts runs from June to November.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Mexico City (MEX) and Cancún (CUN) are the main gateways, with many international flights to Guadalajara, Puerto Vallarta, Los Cabos and other cities.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Domestic flights cover long distances; first-class buses are comfortable and reliable. Use ride-hailing apps or official taxis in cities.$c$), "budget"=coalesce(nullif("budget",''),$c$Good value outside resort zones; Cancún, Tulum and Los Cabos are the most expensive.$c$), "safety"=coalesce(nullif("safety",''),$c$Safety varies a lot by region; stick to well-travelled areas, avoid travelling by road at night, and check your government's travel advice.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities can visit visa-free for tourism. Check Mexico's official consular site before travel.$c$), "currency"=coalesce(nullif("currency",''),$c$Mexican Peso (MXN)$c$), "language"=coalesce(nullif("language",''),$c$Spanish$c$), "timezone"=coalesce(nullif("timezone",''),$c$Several zones; Mexico City UTC−6$c$), "updatedAt"=now() where slug='mexico';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Medinas, mountains and the Sahara, a short flight from Europe.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Morocco blends Arab, Berber and Andalusian influences. Marrakech and Fes are known for their historic medinas and souks, Chefchaouen for its blue-washed streets, Essaouira for its breezy Atlantic port, and the Atlas Mountains and Sahara dunes for trekking and desert camps.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$March to May and September to November for comfortable temperatures. Summer is very hot inland; winter nights are cold in the desert and mountains.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Marrakech (RAK), Casablanca (CMN), Fes (FEZ) and Tangier (TNG) have international flights; ferries cross from Spain to Tangier.$c$), "transportation"=coalesce(nullif("transportation",''),$c$The Al Boraq high-speed train links Tangier and Casablanca; regular trains reach Fes and Marrakech. Buses and grand taxis cover other routes, and tours are the easiest way to reach the desert.$c$), "budget"=coalesce(nullif("budget",''),$c$Good value, especially outside upscale riads and resorts.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe. Expect persistent touts and unofficial guides in the medinas; agree prices before services.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities, including EU, UK and US citizens, can visit visa-free for short stays. Check Morocco's official consular site.$c$), "currency"=coalesce(nullif("currency",''),$c$Moroccan Dirham (MAD)$c$), "language"=coalesce(nullif("language",''),$c$Arabic, Amazigh (Berber); French widely spoken$c$), "timezone"=coalesce(nullif("timezone",''),$c$UTC+1 (UTC+0 during Ramadan)$c$), "updatedAt"=now() where slug='morocco';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Atlantic light, historic cities and easy-going coastline.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Portugal is compact and varied: Lisbon's hills and trams, Porto's riverside and port wine cellars, the vineyards of the Douro Valley, the beaches and cliffs of the Algarve, and the islands of Madeira and the Azores.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$April to June and September to October for warm weather without peak crowds. July and August are busiest on the Algarve.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Lisbon (LIS), Porto (OPO) and Faro (FAO) are the main airports, with wide European connections.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Trains link Lisbon, Porto and the Algarve; buses fill gaps. A car is handy for the Douro and rural areas.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid-range and good value by Western European standards, though Lisbon prices have risen.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe; watch for pickpockets on Lisbon's trams and in busy areas.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Schengen area: EU/EEA citizens enter freely; many other nationalities can visit visa-free for short stays. Check the official Portuguese visa site.$c$), "currency"=coalesce(nullif("currency",''),$c$Euro (EUR)$c$), "language"=coalesce(nullif("language",''),$c$Portuguese$c$), "timezone"=coalesce(nullif("timezone",''),$c$WET (UTC+0), WEST (UTC+1) in summer; Azores UTC−1$c$), "updatedAt"=now() where slug='portugal';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Safari, winelands and dramatic coastline at the tip of Africa.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$South Africa offers big-game safaris in Kruger and private reserves, the city, mountain and coastal scenery of Cape Town, the Cape Winelands, and the Garden Route road trip. Johannesburg is a major hub with museums on the country's history.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$May to September is the dry season and best for safaris; November to March is summer and ideal for Cape Town and the coast.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Johannesburg (JNB) and Cape Town (CPT) are the main international airports.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Domestic flights link the main cities; self-drive is popular for the Garden Route and Winelands. Use ride-hailing apps in cities.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid-range and good value for travellers paying in foreign currency; private game reserves are the main expense.$c$), "safety"=coalesce(nullif("safety",''),$c$Crime is a concern in some areas: avoid walking alone at night, keep valuables out of sight, and follow local advice.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities can visit visa-free for short stays. Check South Africa's official Department of Home Affairs site.$c$), "currency"=coalesce(nullif("currency",''),$c$South African Rand (ZAR)$c$), "language"=coalesce(nullif("language",''),$c$11 official languages; English widely used$c$), "timezone"=coalesce(nullif("timezone",''),$c$SAST (UTC+2)$c$), "updatedAt"=now() where slug='south-africa';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Sunshine, tapas and some of Europe's liveliest cities.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Spain mixes vibrant cities with long coastlines and islands. Barcelona is known for Gaudí's architecture, Madrid for its art museums and nightlife, and Andalusia for Seville, Granada's Alhambra and Córdoba's Mezquita. The Basque Country is famous for food, and the Balearic and Canary Islands for beaches.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$April to June and September to October for pleasant weather. July and August are very hot inland and busy on the coast.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Madrid (MAD) and Barcelona (BCN) are the main hubs, with many international airports on the coasts and islands.$c$), "transportation"=coalesce(nullif("transportation",''),$c$High-speed AVE trains link Madrid with Barcelona, Seville, Málaga and Valencia; buses cover smaller towns. Domestic flights reach the islands.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid-range; Barcelona, Madrid and the islands in summer are the most expensive.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe; pickpocketing is common in Barcelona and Madrid tourist areas.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Schengen area: EU/EEA citizens enter freely; many other nationalities can visit visa-free for short stays. Check the official Spanish visa site.$c$), "currency"=coalesce(nullif("currency",''),$c$Euro (EUR)$c$), "language"=coalesce(nullif("language",''),$c$Spanish; Catalan, Basque and Galician regionally$c$), "timezone"=coalesce(nullif("timezone",''),$c$CET (UTC+1), CEST (UTC+2) in summer; Canary Islands UTC+0$c$), "updatedAt"=now() where slug='spain';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$The Serengeti, Kilimanjaro and the spice island of Zanzibar.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Tanzania is home to the Serengeti, the Ngorongoro Crater and Tarangire, among Africa's finest safari areas. Mount Kilimanjaro is Africa's highest peak, and Zanzibar adds beaches, coral reefs and the historic Stone Town.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$June to October for dry-season safaris; January to February for calving season in the southern Serengeti. The long rains fall roughly March to May.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Kilimanjaro International (JRO) serves the northern safari circuit; Dar es Salaam (DAR) and Zanzibar (ZNZ) also have international flights.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Safaris are run by operators by road or with light-aircraft hops between parks. Ferries and short flights connect the mainland to Zanzibar.$c$), "budget"=coalesce(nullif("budget",''),$c$Safaris and park fees make it a mid to high-cost destination; Zanzibar has a wider range of options.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe on organised trips. Use normal city caution in Dar es Salaam and follow guides' instructions in the parks.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Most visitors need a visa, available as an e-visa or in some cases on arrival. Check Tanzania's official immigration site.$c$), "currency"=coalesce(nullif("currency",''),$c$Tanzanian Shilling (TZS); US dollars widely used for safaris$c$), "language"=coalesce(nullif("language",''),$c$Swahili, English$c$), "timezone"=coalesce(nullif("timezone",''),$c$EAT (UTC+3)$c$), "updatedAt"=now() where slug='tanzania';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Temples, street food and island beaches.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Thailand combines Bangkok's temples and street food with the old capitals of Ayutthaya and Sukhothai, the mountains and night markets of Chiang Mai, and islands such as Phuket, Koh Samui, Koh Phi Phi and Koh Lanta.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$November to February is the cool, dry season and the most popular time. Rain patterns differ between the Andaman and Gulf coasts.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Bangkok Suvarnabhumi (BKK) is the main hub; Don Mueang (DMK), Phuket (HKT) and Chiang Mai (CNX) also have international flights.$c$), "transportation"=coalesce(nullif("transportation",''),$c$Domestic flights and overnight trains link the regions; ferries serve the islands. Use ride-hailing apps or metered taxis in Bangkok.$c$), "budget"=coalesce(nullif("budget",''),$c$Good value overall, with higher prices on the most popular islands.$c$), "safety"=coalesce(nullif("safety",''),$c$Generally safe. Watch for common scams in tourist areas and take care on roads and scooters.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Many nationalities can enter visa-exempt for tourism, but the rules have changed several times recently. Check the official Thai government site before travel.$c$), "currency"=coalesce(nullif("currency",''),$c$Thai Baht (THB)$c$), "language"=coalesce(nullif("language",''),$c$Thai$c$), "timezone"=coalesce(nullif("timezone",''),$c$ICT (UTC+7)$c$), "updatedAt"=now() where slug='thailand';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Iconic cities, national parks and road trips on a grand scale.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$The United States ranges from New York, Los Angeles, Miami and San Francisco to national parks such as Yellowstone, Yosemite and the Grand Canyon. Each region has its own food and music, and road trips are a classic way to travel.$c$ else "overview" end, "bestTimeToVisit"=coalesce(nullif("bestTimeToVisit",''),$c$Depends on the region: spring and autumn suit most cities, summer is best for northern national parks, and winter is ideal for Florida and the Southwest.$c$), "howToGetThere"=coalesce(nullif("howToGetThere",''),$c$Major international gateways include New York (JFK), Los Angeles (LAX), Miami (MIA), Chicago (ORD) and San Francisco (SFO).$c$), "transportation"=coalesce(nullif("transportation",''),$c$Domestic flights cover long distances; a rental car is usually needed outside the big cities. New York, Chicago and Washington have good public transport.$c$), "budget"=coalesce(nullif("budget",''),$c$Mid to high; big-city hotels are expensive, and tipping is expected in restaurants and for many services.$c$), "safety"=coalesce(nullif("safety",''),$c$Safety varies by city and neighbourhood; follow local advice. In national parks, respect wildlife and weather warnings.$c$), "visaInfo"=coalesce(nullif("visaInfo",''),$c$Visa Waiver Program travellers need an approved ESTA before flying; others need a visa. Check the official US government sites.$c$), "currency"=coalesce(nullif("currency",''),$c$US Dollar (USD)$c$), "language"=coalesce(nullif("language",''),$c$English$c$), "timezone"=coalesce(nullif("timezone",''),$c$Six main zones, UTC−5 to UTC−10$c$), "updatedAt"=now() where slug='united-states';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Safaris, deserts and coastlines across a vast continent.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Africa's destinations on Riversmag range from the medinas of Morocco and the pyramids of Egypt to safari country in Kenya, Tanzania and South Africa. Use the country guides below to plan routes, seasons and practicalities.$c$ else "overview" end, "updatedAt"=now() where slug='africa';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$From national parks to beaches and ancient ruins.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$The Americas cover everything from the cities and national parks of the United States and Canada to Mexico's ruins and beaches and Brazil's rainforest and coast. Pick a country guide below to start planning.$c$ else "overview" end, "updatedAt"=now() where slug='americas';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Temples, megacities and island escapes.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Asia on Riversmag focuses on Japan, Thailand and Indonesia: neon cities and historic temples, island beaches, street food and well-connected transport. Start with a country or city guide below.$c$ else "overview" end, "updatedAt"=now() where slug='asia';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Historic cities, varied cuisine and easy rail connections.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Europe's destinations include France, Italy, Spain, Portugal and Greece, with art cities, coastlines and islands that are easy to combine by train or short flight. Choose a country or city guide below.$c$ else "overview" end, "updatedAt"=now() where slug='europe';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Ancient history and desert landscapes.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Our Middle East guides start with Egypt and Cairo, home to the Pyramids of Giza and the Nile. Use the guides below to plan when to go and how to get around.$c$ else "overview" end, "updatedAt"=now() where slug='middle-east';
update "Destination" set "tagline"=case when coalesce("tagline",'')='' or "tagline" like '%made simple:%' then $c$Reefs, outback and island life in the South Pacific.$c$ else "tagline" end, "overview"=case when length(coalesce("overview",''))<120 then $c$Oceania covers Australia, New Zealand and the Pacific islands. We are building out guides for this region; in the meantime, use our travel resources to plan flights, insurance and connectivity.$c$ else "overview" end, "updatedAt"=now() where slug='oceania';
commit;
select (select count(*) from "Destination" where "isActive" and "coverImage" is null) as dest_sans_photo,
       (select count(*) from "Destination" where "isActive" and length(coalesce(overview,''))<120) as dest_sans_texte,
       (select count(*) from "Article" where "authorName"='Maya Chen') as maya_restants,
       (select name from "Author" limit 1) as auteur;